let aiEditorialAbPending=[],aiEditorialAbSelectedId=null,aiEditorialAbRunId=null,aiEditorialAbGenerated=0,aiEditorialAbTarget=40,aiEditorialAbSkipped=new Set;
const aiEditorialAbMediaLabel={ANIME:'애니',FILM:'영화',TV:'TV',BOOK:'문학',MANGA:'만화',OTHER:'기타'};
function aiEditorialAbReviewForm(item){return`<form class="ai-ab-review" data-ai-ab-item="${esc(item.id)}"><header><span>${esc(aiEditorialAbMediaLabel[item.mediaType]||item.mediaType)}</span><strong>${esc(item.title)}</strong></header><p class="ai-ab-review-help">두 문구를 각각 평가해 주세요. 어느 쪽이 AI인지는 공개되지 않습니다.</p><div class="ai-ab-variants"><label><b>A</b><q>${esc(item.variantA)}</q><span>점수 <select name="scoreA" aria-label="A 문구 점수">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></span><span><input type="checkbox" name="qualityPassA"> 품질 통과</span><span class="danger"><input type="checkbox" name="spoilerA"> 스포일러 발견</span></label><label><b>B</b><q>${esc(item.variantB)}</q><span>점수 <select name="scoreB" aria-label="B 문구 점수">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></span><span><input type="checkbox" name="qualityPassB"> 품질 통과</span><span class="danger"><input type="checkbox" name="spoilerB"> 스포일러 발견</span></label></div><fieldset><legend>더 추천하고 싶은 문구</legend><label><input type="radio" name="preference" value="A" required> A</label><label><input type="radio" name="preference" value="B"> B</label><label><input type="radio" name="preference" value="tie"> 비슷함</label></fieldset><label class="ai-ab-note">검수 메모<input name="note" maxlength="1000" placeholder="판단 근거(선택)"></label><div class="ai-ab-review-actions"><button type="button" data-ai-ab-skip="${esc(item.id)}">모르는 작품 · 건너뛰기</button><button type="submit">평가 저장</button></div></form>`}
function renderAiEditorialAbWorks(){const list=$('#aiEditorialAbList');if(!list)return;const pending=aiEditorialAbPending,available=pending.filter(item=>!aiEditorialAbSkipped.has(String(item.id)));if(aiEditorialAbSelectedId&&!pending.some(item=>String(item.id)===String(aiEditorialAbSelectedId)))aiEditorialAbSelectedId=null;if(aiEditorialAbSelectedId&&aiEditorialAbSkipped.has(String(aiEditorialAbSelectedId)))aiEditorialAbSelectedId=null;if(!aiEditorialAbSelectedId)aiEditorialAbSelectedId=available[0]?.id??null;const selected=pending.find(item=>String(item.id)===String(aiEditorialAbSelectedId)),picker=pending.length?`<div class="ai-ab-work-picker"><label>평가할 작품 선택<select data-ai-ab-work-select aria-label="평가할 작품 선택"><option value="">작품을 선택하세요</option>${pending.map(item=>`<option value="${esc(item.id)}" ${selected&&String(selected.id)===String(item.id)?'selected':''}>${aiEditorialAbSkipped.has(String(item.id))?'↷ ':''}${esc(aiEditorialAbMediaLabel[item.mediaType]||item.mediaType)} · ${esc(item.title)}</option>`).join('')}</select></label><span>미평가 ${pending.length}개 · 이번 접속에서 건너뜀 ${aiEditorialAbSkipped.size}개</span></div>`:'';if(!pending.length){list.innerHTML=`<p class="review-empty">${aiEditorialAbGenerated<aiEditorialAbTarget?'다음 후보를 생성하면 검수 문구가 표시됩니다.':'내 계정으로 평가할 수 있는 생성 문구를 모두 검수했습니다. 다른 독립 평가자의 검수를 기다립니다.'}</p>`;return}list.innerHTML=picker+(selected?aiEditorialAbReviewForm(selected):`<div class="ai-ab-all-skipped"><strong>아는 작품을 모두 평가했어요.</strong><p>건너뛴 작품은 평가로 저장되지 않았습니다. 작품 선택 목록에서 다시 고르거나 아래 버튼으로 처음부터 확인할 수 있어요.</p><button type="button" data-ai-ab-reset-skips>건너뛴 작품 다시 보기</button></div>`)}
function chooseAiEditorialAbWork(id){if(!id)return;aiEditorialAbSkipped.delete(String(id));aiEditorialAbSelectedId=id;renderAiEditorialAbWorks()}
function skipAiEditorialAbWork(id){const current=aiEditorialAbPending.findIndex(item=>String(item.id)===String(id));aiEditorialAbSkipped.add(String(id));const ordered=[...aiEditorialAbPending.slice(current+1),...aiEditorialAbPending.slice(0,current)],next=ordered.find(item=>!aiEditorialAbSkipped.has(String(item.id)));aiEditorialAbSelectedId=next?.id??null;renderAiEditorialAbWorks();toast('건너뛴 작품은 평가 결과에 포함되지 않습니다.')}
async function loadAiEditorialAb(){const summary=$('#aiEditorialAbSummary'),list=$('#aiEditorialAbList');if(!summary||!list)return;summary.innerHTML='<p class="review-empty">확대 A/B 검수 상태를 확인하고 있어요.</p>';list.innerHTML='';try{const response=await fetch('/api/ai-editorial-ab',{cache:'no-store'}),data=await response.json();if(response.status===401||response.status===403){summary.innerHTML='<p class="review-empty">지정된 검수자만 블라인드 평가에 참여할 수 있습니다.</p>';return}if(!response.ok)throw new Error(data.error||'A/B 검수 상태를 불러오지 못했습니다.');if(!data.run){summary.innerHTML=`<article class="ai-ab-empty"><strong>${esc(data.sampleSize)}개 작품 고정 표본</strong><p>애니·영화·문학·만화를 같은 수로 나누고, 작품마다 2명 이상이 서로의 답을 보지 않고 평가합니다.</p><button type="button" data-ai-ab-action="start">확대 A/B 시작</button></article>`;return}if(aiEditorialAbRunId!==data.run.id){aiEditorialAbRunId=data.run.id;aiEditorialAbSelectedId=null;aiEditorialAbSkipped.clear()}const m=data.metrics,percent=value=>`${Math.round(Number(value||0)*100)}%`,gate=(ok,label)=>`<span class="${ok?'pass':'wait'}">${ok?'✓':'○'} ${label}</span>`;summary.innerHTML=`<div class="ai-ab-run"><header><strong>${esc(data.run.status==='promoted'?'기본 활성화 승인':'검수 진행 중')}</strong><span>${esc(data.run.model)}</span></header><div class="ai-ab-numbers"><b>${esc(m.generated)}/${esc(m.target)}<small>AI 생성</small></b><b>${esc(m.reviewed)}/${esc(m.target)}<small>2인 검수 작품</small></b><b>${esc(m.uniqueReviewers)}명<small>독립 평가자</small></b><b>${percent(m.agreementRate)}<small>평가 일치율</small></b><b>${percent(m.passRate)}<small>통과율</small></b><b>${esc(m.spoilers)}건<small>AI 스포일러</small></b><b>${Number(m.preferenceUplift)>=0?'+':''}${percent(m.preferenceUplift)}p<small>선호 격차</small></b></div><div class="ai-ab-gates">${gate(m.gates.sample,'40작품 전체 생성')}${gate(m.gates.humanReview,'40작품·각 2인 검수')}${gate(m.gates.reviewerDiversity,'평가자 2명 이상')}${gate(m.gates.agreement,'일치율 70%')}${gate(m.gates.passRate,'통과율 80%')}${gate(m.gates.spoilers,'AI 스포일러 0')}${gate(m.gates.preference,'AI 선호 +5%p')}</div>${data.run.status!=='promoted'&&m.generated<m.target?'<button type="button" data-ai-ab-action="generate">다음 5작품 AI 후보 생성</button>':''}</div>`;aiEditorialAbPending=(data.items||[]).filter(item=>!item.reviewed);aiEditorialAbGenerated=m.generated;aiEditorialAbTarget=m.target;renderAiEditorialAbWorks()}catch(error){summary.innerHTML=`<p class="review-empty">${esc(error.message)}</p>`}}
async function runAiEditorialAbAction(action,button){button.disabled=true;try{const response=await fetch('/api/ai-editorial-ab',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action})}),data=await response.json();if(!response.ok)throw new Error(data.error||'A/B 작업을 실행하지 못했습니다.');await Promise.all([loadAiEditorialAb(),loadAiAssistStatus()]);toast(action==='start'?'40작품 블라인드 검수를 만들었습니다.':'다음 AI 후보를 생성했습니다.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function submitAiEditorialAbReview(form){const preference=form.querySelector('[name="preference"]:checked')?.value;if(!preference)return toast('더 추천하고 싶은 문구를 선택해 주세요.');const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const response=await fetch('/api/ai-editorial-ab',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'review',itemId:Number(form.dataset.aiAbItem),preference,scoreA:Number(form.scoreA.value),scoreB:Number(form.scoreB.value),qualityPassA:form.qualityPassA.checked,qualityPassB:form.qualityPassB.checked,spoilerA:form.spoilerA.checked,spoilerB:form.spoilerB.checked,note:form.note.value})}),data=await response.json();if(!response.ok)throw new Error(data.error||'검수를 저장하지 못했습니다.');await Promise.all([loadAiEditorialAb(),loadAiAssistStatus()]);toast(data.run?.status==='promoted'?'모든 기준을 충족해 AI 문구를 기본 활성화했습니다.':'블라인드 평가를 저장했습니다.')}catch(error){toast(error.message);button.disabled=false}}
$('#aiEditorialAbSummary').onclick=e=>{const button=e.target.closest('[data-ai-ab-action]');if(button)runAiEditorialAbAction(button.dataset.aiAbAction,button)};
$('#aiEditorialAbList').onchange=e=>{const select=e.target.closest('[data-ai-ab-work-select]');if(select)chooseAiEditorialAbWork(select.value)};
$('#aiEditorialAbList').onclick=e=>{const skip=e.target.closest('[data-ai-ab-skip]');if(skip){skipAiEditorialAbWork(skip.dataset.aiAbSkip);return}if(e.target.closest('[data-ai-ab-reset-skips]')){aiEditorialAbSkipped.clear();aiEditorialAbSelectedId=null;renderAiEditorialAbWorks()}};
$('#aiEditorialAbList').onsubmit=e=>{const form=e.target.closest('[data-ai-ab-item]');if(form){e.preventDefault();submitAiEditorialAbReview(form)}};
